        "archive": {
            "title": "Archive",
            "description": "An OpenTok Archive",
            "type": "object",
            "properties": {
                "createdAt": {
                    "type": "integer"
                },
                "duration": {
                    "type": "integer",
                    "minimum": 0
                },
                "id": {
                    "type": "string",
                    "pattern": "^[a-z0-9]{8}-[a-z0-9]{4}-[a-z0-9]{4}-[a-z0-9]{4}-[a-z0-9]{12}$"
                },
                "name": {
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "partnerId": {
                    "type": "integer"
                },
                "reason": {
                    "type": "string"
                },
                "sessionId": {
                    "type": "string"
                },
                "size": {
                    "type": "integer",
                    "minimum": 0
                },
                "status": {
                    "type": "string",
                    "enum": [
                        "available",
                        "started",
                        "stopped",
                        "failed",
                        "deleted",
                        "uploaded",
                        "expired",
                        "paused"
                    ]
                },
                "url": {
                    "type": [
                        "string",
                        "null"
                    ]
                },
                "hasVideo": {
                    "type": "boolean"
                },
                "hasAudio": {
                    "type": "boolean"
                }
            },
            "required": [
                "id",
                "partnerId",
                "sessionId",
                "status"
            ]
