            "pattern": ".*"
        },
        "modulesArray": {
            "type": "array",
            "items": {
                "$ref": "#/definitions/module"
            }
        },
        "targetsArray": {
            "type": "array",
            "items": {
                "$ref": "#/definitions/target"
            }
        }
    }
}

