        },
        "integrationSettings": {
            "type": "object",
            "title": "Integration Settings",
            "properties": {
                "templateId": {
                    "type": "string",
                    "title": "Email Template ID"
                },
                "giftId": {
                    "type": "string"
                },
                "utid": {
                    "type": "string"
                }
            }
        }
    }
}

